repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 57), ('mia', 31), ('noor', 16), ('noor', 43), ('omar', 14), ('pia', 5)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.paging.py:
"""Pages of donations."""


def page_count(n_items, page_size):
    """Return how many pages are needed to show n_items, page_size to a page."""
    return n_items // page_size


def page(donations, number, page_size):
    """Return page `number` of donations. Pages are numbered from 1."""
    start = (number - 1) * page_size
    return donations[start:start + page_size]


def all_pages(donations, page_size):
    """Return every page of donations, in order."""
    return [page(donations, n, page_size) for n in range(1, page_count(len(donations), page_size) + 1)]


def donor_names(donations):
    """Return the distinct donor values, in first-seen order."""
    names = []
    for x in donations:
        if x.donor not in names:
            names.append(x.donor)
    return names


def largest_pounds(donations):
    """Return the largest pounds, or None when there are no donations."""
    values = [x.pounds for x in donations]
    return max(values) if values else None
